/*The BankCrad is a card that can deposit or withdraw money.*/
class BankCard {
  /*The unique identifier of the bank card*/
  CardID: number;
  /*The status of the bank card*/
  CardStatus: CardStatus;
  /*The catalog of the bank card*/
  Catalog: CardCatalog;
  /*The password of the bank card*/
  Password: number;
  /*The balance of the bank card*/
  Balance: number;
  /*The user who owns the bank card*/
  BelongedUser: User;
}
/*Bank user information.*/
class User {
  /*The id of the user*/
  UserID: number;
  /*The name of the user*/
  Name: string;
  /*The address of the user*/
  Address: string;
  /*The bank card owned by the user*/
  OwnedCard: BankCard;
}
enum CardStatus {
  NORMAL = "NORMAL",
  SUSPEND = "SUSPEND",
  CANNEL = "CANNEL",
}
enum CardCatalog {
  CREDIT = "CREDIT",
  DESPOSIT = "DESPOSIT",
}
const map = new Map();
map.set(BankCard, []);
map.set(User, []);
const getRepository = <T,>(clazz: new (...args: any[]) => T) => {
  return map.get(clazz) as T[];
};
export { CardStatus, CardCatalog, BankCard, User, getRepository };

typescript.originalService:
class AutomatedTellerMachineSystem_AutoGenerated {
  /*SystemVariable Start*/
  PasswordValidated: boolean;
  WithdrawedNumber: number;
  InputCard: BankCard;
  CardIDValidated: boolean;
  IsDeposit: boolean;
  IsWithdraw: boolean;
  DepositedNumber: number;
  /*SystemVariable End*/

  /*find the card with the provided card id,
   *if the card exists, means card id is validated,
   *and the input card will be used in the next operation,
   *if not exist, means the card id is invalidated*/
  inputCard(cardid: number): boolean {
    /*Definition Start*/
    let obs: BankCard[] = l({
      logic: () =>
        getRepository(BankCard).filter(
          (o: any) =>
            l({
              logic: () => o.CardID === cardid,
              description: "o.CardID=cardid",
            }).build().pass,
        ),
      description: "BankCard.allInstance()->select(o|o.CardID=cardid)",
    }).build().pass;
    let inputCard: BankCard = l()
      .if({
        logic: () =>
          l({
            logic: () => StandardOPs.isEmpty(obs) === false,
            description: "obs.isEmpty()=false",
          }),
        description: "obs.isEmpty()=false",
        then: l({
          logic: () =>
            obs.find(
              (o: any) =>
                l({
                  logic: () => StandardOPs.oclIsUndefined(o) === false,
                  description: "o.oclIsUndefined()=false",
                }).build().pass,
            ),
          description: "obs->any(o|o.oclIsUndefined()=false)",
        }),
        else: l({
          logic: () => undefined,
          description: "null",
        }),
      })
      .build().pass;
    let cardIDValidated: boolean = l({
      logic: () => StandardOPs.isEmpty(obs) === false,
      description: "obs.isEmpty()=false",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => StandardOPs.oclIsTypeOf(cardid, Integer),
        description: "cardid.oclIsTypeOf(Integer)",
      }).build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    return l({
      execute: () => (this.InputCard = inputCard),
      description: "self.InputCard=inputCard",
    })
      .and({
        execute: () => (this.CardIDValidated = cardIDValidated),
        description: "self.CardIDValidated=cardIDValidated",
      })
      .and({
        execute: () => cardIDValidated,
        description: "result=cardIDValidated",
      })
      .build().value;
    /*Postcondition End*/
  }
}
export { AutomatedTellerMachineSystem_AutoGenerated };

